public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    if (n == 0 || start == null || end == null || paths == null) {
        throw new IllegalArgumentException("Invalid input");
    }

    Map<Integer, List<Integer>> graph = new HashMap<>();
    for (int[] path : paths) {
        int src = path[0];
        int dest = path[1];
        graph.putIfAbsent(src, new ArrayList<>());
        graph.putIfAbsent(dest, new ArrayList<>());
        graph.get(src).add(dest);
        graph.get(dest).add(src);
    }

    boolean[] visited = new boolean[n];
    Queue<Integer> queue = new LinkedList<>();
    queue.add(start[0]);
    visited[start[0]] = true;

    while (!queue.isEmpty()) {
        int current = queue.poll();
        if (current == end[0]) {
            return "can be travelled";
        }
        for (int neighbor : graph.getOrDefault(current, new ArrayList<>())) {
            if (!visited[neighbor]) {
                visited[neighbor] = true;
                queue.add(neighbor);
            }
        }
    }

    return "cannot be travelled";
}

public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    if (n <= 0 || start == null || end == null || paths == null) {
        throw new IllegalArgumentException("Invalid input");
    }

    boolean[][] grid = new boolean[n][n];
    for (int[] path : paths) {
        if (path.length != 2) {
            throw new IllegalArgumentException("Invalid path");
        }
        int x1 = path[0];
        int y1 = path[1];
        if (x1 < 0 || x1 >= n || y1 < 0 || y1 >= n) {
            throw new IllegalArgumentException("Invalid path coordinates");
        }
        grid[x1][y1] = true;
    }

    int startX = start[0];
    int startY = start[1];
    if (startX < 0 || startX >= n || startY < 0 || startY >= n) {
        throw new IllegalArgumentException("Invalid start coordinates");
    }

    int endX = end[0];
    int endY = end[1];
    if (endX < 0 || endX >= n || endY < 0 || endY >= n) {
        throw new IllegalArgumentException("Invalid end coordinates");
    }

    boolean[][] visited = new boolean[n][n];
    return dfs(grid, startX, startY, endX, endY, visited) ? "can be travelled" : "cannot be travelled";
}

