public static String appx(String word1, String word2) {
    if (word1 == null || word2 == null) {
        throw new IllegalArgumentException("Input strings cannot be null");
    }

    Set<Character> commonChars = new HashSet<>();
    for (char c : word1.toCharArray()) {
        commonChars.add(c);
    }

    int count = 0;
    for (char c : word2.toCharArray()) {
        if (commonChars.contains(c)) {
            count++;
            commonChars.remove(c);
        }
    }

    int sumOfLengths = word1.length() + word2.length();
    if (sumOfLengths == 0) {
        throw new IllegalArgumentException("Sum of word lengths cannot be zero");
    }

    int gcd = gcd(count, sumOfLengths);
