        throw new IllegalArgumentException("Invalid input");
    }

    int[] remainderCounts = new int[k];
    for (int num : arr) {
        int remainder = ((num % k) + k) % k; // Ensure non-negative remainder
        remainderCounts[remainder]++;
    }

    if (remainderCounts[0] % 2 != 0) {
        return false; // Zero remainder must be even
    }

    for (int i = 1; i <= k / 2; i++) {
        if (remainderCounts[i] != remainderCounts[k - i]) {
            return false; // Pairs of remainders must match
        }
    }

    return true;
}

public boolean canArrange(int[] arr, int k) {
    int n = arr.length;
    if (n % 2 != 0) {
        return false;
    }

    HashMap<Integer, Integer> remainderCount = new HashMap<>();

    for (int num : arr) {
        int remainder = ((num % k) + k) % k; // Ensure non-negative remainder
        remainderCount.put(remainder, remainderCount.getOrDefault(remainder, 0) + 1);
    }

    for (int remainder : remainderCount.keySet()) {
        if (remainder == 0) {
            if (remainderCount.get(remainder) % 2 != 0) {
                return false;
            }
        } else if (remainderCount.containsKey(k - remainder)) {
            if (!remainderCount.get(remainder).equals(remainderCount.get(k - remainder))) {
                return false;
            }
        } else {
            return false;
        }
    }

    return true;
}

