public int minInsertions(String s) {
    int leftBalance = 0;
    int rightBalance = 0;
    int insertions = 0;

    for (int i = 0; i < s.length(); i++) {
        if (s.charAt(i) == '(') {
            leftBalance++;
            if (rightBalance > 0) {
                insertions++;
                rightBalance--;
            }
        } else {
            rightBalance++;
            if (leftBalance > 0) {
                leftBalance--;
            } else {
                insertions++;
            }
        }
    }

    return insertions + leftBalance * 2 + rightBalance * 2;
}

public int minInsertions(String s) {
    int balance = 0; // Track the balance of parentheses
    int insertions = 0; // Count the number of insertions needed

    for (int i = 0; i < s.length(); ) {
        if (s.charAt(i) == '(') {
            balance++;
            i++;
        } else {
            if (i + 1 < s.length() && s.charAt(i + 1) == ')') {
                i += 2;
            } else {
                insertions++;
                i++;
            }
            if (balance > 0) {
                balance--;
            } else {
                insertions++;
            }
        }
    }

    insertions += 2 * balance; // Each unmatched '(' needs a ')' and vice versa

    return insertions;
}

