public int minInsertions(String s) {
    int open = 0;
    int close = 0;
    int insertions = 0;

    for (int i = 0; i < s.length(); i++) {
        char c = s.charAt(i);

        if (c == '(') {
            open++;
        } else {
            close++;
            if (i + 1 < s.length() && s.charAt(i + 1) == ')') {
                i++; // Skip the next character as we found a balanced pair
            } else {
                insertions++; // Need an additional closing parenthesis
            }
        }
    }

    // Unmatched opening and closing parentheses
    insertions += open * 2 + close * 2;
    insertions -= Math.min(open * 2, close * 2);

    return insertions;
}

public int minInsertions(String s) {
    int balance = 0;
    int insertions = 0;

    for (int i = 0; i < s.length(); i++) {
        if (s.charAt(i) == '(') {
            if (i + 1 < s.length() && s.charAt(i + 1) == ')') {
                i++; // Skip the next character as it forms a balanced pair
            } else {
                insertions++; // Need to insert a ')' to balance
            }
            balance++;
        } else if (s.charAt(i) == ')') {
            balance--;
            if (balance < 0) {
                insertions++; // Need to insert a '(' to balance
                balance = 0; // Reset balance to 0 after insertion
            }
        }
    }

    return insertions + balance * 2; // Each remaining '(' needs two ')' to balance
}

public int minOperations(int n) {
