public int minOperations(int n) {
    int totalSum = 0;
    int targetValue = 0;
    for (int i = 0; i < n; i++) {
        totalSum += (2 * i) + 1;
    }
    targetValue = totalSum / n;

    int minOperations = 0;
    for (int i = 0; i < n / 2; i++) {
        int currentValue = (2 * i) + 1;
        int diff = targetValue - currentValue;
        minOperations += diff;
    }

    return minOperations;
}

