    List<Integer> fibs = new ArrayList<>();
    int a = 1, b = 1;
    fibs.add(a);
    fibs.add(b);
    while (b + a <= k) {
        int temp = a + b;
        a = b;
        b = temp;
        fibs.add(b);
    }

    int count = 0;
    for (int i = fibs.size() - 1; i >= 0; i--) {
        if (fibs.get(i) <= k) {
            k -= fibs.get(i);
            count++;
            if (k == 0) {
                break;
            }
        }
    }

    return count;
}

