public String makeGood(String s) {
    StringBuilder stack = new StringBuilder();
    for (char c : s.toCharArray()) {
        if (stack.length() == 0) {
            stack.append(c);
        } else {
            char lastChar = stack.charAt(stack.length() - 1);
            if (Character.isLowerCase(c) && Character.toUpperCase(c) == lastChar) {
                stack.deleteCharAt(stack.length() - 1);
            } else if (Character.isUpperCase(c) && Character.toLowerCase(c) == lastChar) {
                stack.deleteCharAt(stack.length() - 1);
            } else {
                stack.append(c);
            }
        }
    }
    return stack.toString();
}

public String makeGood(String s) {
    Stack<Character> stack = new Stack<>();
    for (char c : s.toCharArray()) {
        if (!stack.isEmpty() && Math.abs(stack.peek() - c) == 32) {
            stack.pop();
        } else {
            stack.push(c);
        }
    }
    StringBuilder result = new StringBuilder();
    for (char c : stack) {
        result.append(c);
    }
    return result.toString();
}

public String makeGood(String s) {
    StringBuilder stack = new StringBuilder();

    for (char c : s.toCharArray()) {
        if (stack.length() > 0) {
            char last = stack.charAt(stack.length() - 1);
            if (Math.abs(last - c) == 32) {
                stack.deleteCharAt(stack.length() - 1);
                continue;
            }
        }
        stack.append(c);
    }

    return stack.toString();
}

public String makeGood(String s) {
    Stack<Character> stack = new Stack<>();

    for (char c : s.toCharArray()) {
        if (!stack.isEmpty() && Math.abs(stack.peek() - c) == 32) {
            stack.pop();
        } else {
            stack.push(c);
        }
    }

    StringBuilder result = new StringBuilder();
    for (char c : stack) {
        result.append(c);
    }

    return result.toString();
}

