public String getSmallestString(int n, int k) {
    char[] result = new char[n];
    Arrays.fill(result, 'a');
    k -= n;

    int index = n - 1;
    while (k > 0) {
        int add = Math.min(25, k);
        result[index] += add;
        k -= add;
        index--;
    }

    return new String(result);
}

public String getSmallestString(int n, int k) {
    char[] result = new char[n];
    Arrays.fill(result, 'a');
    k -= n;
    for (int i = n - 1; i >= 0; i--) {
        if (k == 0) break;
        int add = Math.min(k, 25);
        result[i] += add;
        k -= add;
    }
    return new String(result);
}

public String getSmallestString(int n, int k) {
    // Initialize the result array with 'a'
    char[] result = new char[n];
    Arrays.fill(result, 'a');
    k -= n; // subtract the value of 'a' * n since each 'a' contributes 1 to the sum

    // Start from the end of the array and try to convert 'a' to the highest possible character
    int index = n - 1;
    while (k > 0) {
        int add = Math.min(25, k); // the maximum we can add is 25 (to convert 'a' to 'z')
        result[index] += add;
        k -= add;
        index--;
    }

    return new String(result);
}

public String getSmallestString(int n, int k) {
    char[] result = new char[n];
    Arrays.fill(result, 'a'); // Initialize the array with 'a' to ensure the smallest possible characters
    k -= n; // Subtract n from k because the initial assumption is that all characters are 'a'

    int index = n - 1; // Start from the end of the array
    while (k > 0) {
        int add = Math.min(25, k); // Calculate the maximum value we can add without exceeding k
        result[index] += add; // Add the calculated value to the current character
        k -= add; // Decrease k by the added value
        index--; // Move to the previous character
    }

    return new String(result); // Convert the char array to a string and return it
}

public String getSmallestString(int n, int k) {
    char[] result = new char[n];
    Arrays.fill(result, 'a'); // Initialize the array with 'a' to ensure the smallest possible letters

    k -= n; // Subtract n from k to account for the initial 'a's

    for (int i = n - 1; i >= 0 && k > 0; i--) {
        int add = Math.min(25, k); // We can add at most 25 to the current position to stay within 'a' to 'z'
        result[i] += add; // Add the value to the current position
        k -= add; // Subtract the added value from k
    }

    return new String(result);
}

