public static List<Integer> findSteppingNumbers(int low, int high) {
        if (low < 0 || high < 0) {
            throw new IllegalArgumentException("Input values must be non-negative.");
        }

        List<Integer> result = new ArrayList<>();
        if (low > high) {
            return result;
        }

        for (int i = 0; i < 10; i++) {
            bfs(i, low, high, result);
        }

        return new ArrayList<>(result.stream().filter(x -> x >= low && x <= high).sorted().toList());
    }

public static List<Integer> findSteppingNumbers(int low, int high) {
        List<Integer> result = new ArrayList<>();
        if (low <= high) {
            bfs(low, high, result);
        }
        return result;
    }

public static List<Integer> findSteppingNumbers(int low, int high) {
        List<Integer> result = new ArrayList<>();
        if (low > high) {
            return result;
        }

        Queue<Integer> queue = new LinkedList<>();
        for (int i = 1; i <= 9; i++) {
            queue.add(i);
        }

        while (!queue.isEmpty()) {
            int current = queue.poll();
            if (current < low) {
                continue;
            }
            if (current > high) {
                break;
            }
            result.add(current);

            int lastDigit = current % 10;
            if (lastDigit != 0) {
                queue.add(current * 10 + lastDigit - 1);
            }
            if (lastDigit != 9) {
                queue.add(current * 10 + lastDigit + 1);
            }
        }

        if (!result.isEmpty() && result.get(0) == 0) {
            result.remove(0);
            result.add(0);
        }

        return result;
    }

public static List<Integer> findSteppingNumbers(int low, int high) {
    // Helper class to check if a number is a stepping number
    class SteppingNumberChecker {
        public static boolean isSteppingNumber(int num) {
            if (num < 10) return true; // Single digit numbers are stepping numbers
            int prevDigit = num % 10;
            num /= 10;
            while (num > 0) {
                int currentDigit = num % 10;
                if (Math.abs(prevDigit - currentDigit) != 1) {
                    return false;
                }
                prevDigit = currentDigit;
                num /= 10;
            }
            return true;
        }
    }

    // Validate input
    if (low > high) {
        return new ArrayList<>();
    }

    List<Integer> result = new ArrayList<>();
    for (int i = low; i <= high; i++) {
        if (SteppingNumberChecker.isSteppingNumber(i)) {
            result.add(i);
        }
    }

    return result;
}

public static List<Integer> findSteppingNumbers(int low, int high) {
    List<Integer> result = new ArrayList<>();
    if (low > high) {
        return result;
    }

    Queue<Integer> queue = new LinkedList<>();
    for (int i = 0; i < 10; i++) {
        queue.add(i);
    }

    while (!queue.isEmpty()) {
        int num = queue.poll();
        if (num >= low && num <= high) {
            result.add(num);
        }
        if (num == 0 || num > high) {
            continue;
        }

        int lastDigit = num % 10;
        if (lastDigit > 0) {
            int nextNum = num * 10 + (lastDigit - 1);
            if (nextNum <= high) {
                queue.add(nextNum);
            }
        }
        if (lastDigit < 9) {
            int nextNum = num * 10 + (lastDigit + 1);
            if (nextNum <= high) {
                queue.add(nextNum);
            }
        }
    }

    result.sort(Integer::compare);
    return result;
}

public static int countDigitOne(int n) {
    if (n < 0) {
        return 0;
    }

    int count = 0;
    long factor = 1;

    while (n / factor > 0) {
        int digit = (int) (n / factor) % 10;
        int lowerNumbers = (int) (n - (n / factor) * factor);
        int higherNumbers = (int) (n / (factor * 10));

        if (digit == 0) {
            count += higherNumbers * factor;
        } else if (digit == 1) {
            count += higherNumbers * factor + lowerNumbers + 1;
        } else {
            count += (higherNumbers + 1) * factor;
        }

        factor *= 10;
    }

    return count;
}

public static int countDigitOne(int n) {
    int count = 0;
    for (long m = 1; m <= n; m *= 10) {
        long a = n / m, b = n % m;
        count += (a + 8) / 10 * m + (a % 10 == 1 ? b + 1 : 0);
    }
    return count;
}

