public static int countDigitOne(int n) {
    if (n < 0) {
        return 0;
    }

    int count = 0;
    for (long i = 1; i <= n; i *= 10) {
        long divided = n / i;
        long remainder = n % i;
        long digit = divided % 10;

        if (digit == 0) {
            count += divided / 10 * i;
        } else if (digit == 1) {
            count += divided / 10 * i + remainder + 1;
        } else {
            count += (divided / 10 + 1) * i;
        }
    }

    return count;
}

public static int countDigitOne(int n) {
    if (n < 0) {
        return 0;
    }

    int count = 0;
    for (long m = 1; m <= n; m *= 10) {
        long a = n / (m * 10);
        long b = (n / m) % 10;
        long c = n % m;

        if (b == 0) {
            count += a * m;
        } else if (b == 1) {
            count += a * m + c + 1;
        } else {
            count += (a + 1) * m;
        }
    }

    return count;
}

