public static int longestLine(int[][] mat) {
    if (mat == null || mat.length == 0 || mat[0].length == 0) {
        return 0;
    }

    int m = mat.length;
    int n = mat[0].length;
    int longest = 0;

    // Arrays to store the count of consecutive 1s in different directions
    int[] horizontal = new int[n];
    int[] vertical = new int[m];
    int[] diagonal = new int[m + n - 1];
    int[] antiDiagonal = new int[m + n - 1];

    for (int i = 0; i < m; i++) {
        for (int j = 0; j < n; j++) {
            if (mat[i][j] == 1) {
                horizontal[j]++;
                vertical[i]++;
                diagonal[i + j]++;
                antiDiagonal[i - j + n - 1]++;

                longest = Math.max(longest, horizontal[j]);
                longest = Math.max(longest, vertical[i]);
                longest = Math.max(longest, diagonal[i + j]);
                longest = Math.max(longest, antiDiagonal[i - j + n - 1]);
            } else {
                horizontal[j] = 0;
                vertical[i] = 0;
                diagonal[i + j] = 0;
                antiDiagonal[i - j + n - 1] = 0;
            }
        }
    }

    return longest;
}

public static int longestLine(int[][] mat) {
    if (mat == null || mat.length == 0 || mat[0].length == 0) {
        return 0;
    }

    int m = mat.length;
    int n = mat[0].length;
    int maxLength = 0;

    // Arrays to store the lengths of consecutive 1s in different directions
    int[][][] directions = {
        {{0, 1}, {0, 0}}, // Horizontal
        {{1, 0}, {0, 0}}, // Vertical
        {{1, 1}, {0, 0}}, // Diagonal
        {{1, -1}, {0, 0}} // Anti-diagonal
    };

    for (int row = 0; row < m; row++) {
        for (int col = 0; col < n; col++) {
            if (mat[row][col] == 0) {
                continue;
            }

            for (int[][] direction : directions) {
                int length = 0;
                int r = row;
                int c = col;

                // Extend the line in the given direction
                while (r >= 0 && r < m && c >= 0 && c < n && mat[r][c] == 1) {
                    length++;
                    r += direction[0][0];
                    c += direction[0][1];
                }

                maxLength = Math.max(maxLength, length);
            }
        }
    }

    return maxLength;
}

public static int longestLine(int[][] mat) {
    if (mat == null || mat.length == 0 || mat[0].length == 0) {
        return 0;
    }

    int m = mat.length;
    int n = mat[0].length;
    int maxLength = 0;

    int[][][] dp = new int[m][n][4]; // dp[i][j][0]: horizontal, dp[i][j][1]: vertical, dp[i][j][2]: diagonal, dp[i][j][3]: anti-diagonal

    for (int i = 0; i < m; i++) {
        for (int j = 0; j < n; j++) {
            if (mat[i][j] == 1) {
                dp[i][j][0] = (j > 0 ? dp[i][j - 1][0] : 0) + 1; // horizontal
                dp[i][j][1] = (i > 0 ? dp[i - 1][j][1] : 0) + 1; // vertical
                dp[i][j][2] = (i > 0 && j > 0 ? dp[i - 1][j - 1][2] : 0) + 1; // diagonal
                dp[i][j][3] = (i > 0 && j < n - 1 ? dp[i - 1][j + 1][3] : 0) + 1; // anti-diagonal

                maxLength = Math.max(maxLength, dp[i][j][0]);
                maxLength = Math.max(maxLength, dp[i][j][1]);
                maxLength = Math.max(maxLength, dp[i][j][2]);
                maxLength = Math.max(maxLength, dp[i][j][3]);
            }
        }
    }

    return maxLength;
}

public static int longestLine(int[][] mat) {
    if (mat == null || mat.length == 0 || mat[0].length == 0) {
        return 0;
    }

    int rows = mat.length;
    int cols = mat[0].length;
    int maxLength = 0;

    // Arrays to keep track of the lengths of consecutive 1s in each direction
    int[][][] count = new int[rows + 1][cols + 1][4];

    for (int i = 1; i <= rows; i++) {
        for (int j = 1; j <= cols; j++) {
            if (mat[i - 1][j - 1] == 1) {
                // Horizontal count
                count[i][j][0] = count[i][j - 1][0] + 1;
                // Vertical count
                count[i][j][1] = count[i - 1][j][1] + 1;
                // Diagonal count
                count[i][j][2] = count[i - 1][j - 1][2] + 1;
                // Anti-diagonal count
                count[i][j][3] = count[i - 1][j + 1][3] + 1;

                // Update the maximum length
                maxLength = Math.max(maxLength, count[i][j][0]);
                maxLength = Math.max(maxLength, count[i][j][1]);
                maxLength = Math.max(maxLength, count[i][j][2]);
                maxLength = Math.max(maxLength, count[i][j][3]);
            }
        }
    }

    return maxLength;
}

public static int longestLine(int[][] mat) {
    if (mat == null || mat.length == 0 || mat[0].length == 0) {
        return 0;
    }

    int m = mat.length;
    int n = mat[0].length;
    int result = 0;

    int[][][] dp = new int[m][n][4];
    /*
    dp[i][j][0] represents the length of the horizontal line ending at (i, j)
    dp[i][j][1] represents the length of the vertical line ending at (i, j)
    dp[i][j][2] represents the length of the diagonal line ending at (i, j)
    dp[i][j][3] represents the length of the anti-diagonal line ending at (i, j)
    */

    for (int i = 0; i < m; i++) {
        for (int j = 0; j < n; j++) {
            if (mat[i][j] == 1) {
                dp[i][j][0] = (j > 0 ? dp[i][j - 1][0] : 0) + 1;
                dp[i][j][1] = (i > 0 ? dp[i - 1][j][1] : 0) + 1;
                dp[i][j][2] = (i > 0 && j > 0 ? dp[i - 1][j - 1][2] : 0) + 1;
                dp[i][j][3] = (i > 0 && j < n - 1 ? dp[i - 1][j + 1][3] : 0) + 1;
                result = Math.max(result, dp[i][j][0]);
                result = Math.max(result, dp[i][j][1]);
                result = Math.max(result, dp[i][j][2]);
                result = Math.max(result, dp[i][j][3]);
            }
        }
    }
    return result;
}

public static String addThousandSeparator(int n) {
    if (n < 0) {
        throw new IllegalArgumentException("Input must be a non-negative integer.");
    }
    return String.format("%,d", n).replaceAll(",", ".");
}

public static String addThousandSeparator(int n) {
    String numStr = Integer.toString(n);
    StringBuilder result = new StringBuilder();
    int length = numStr.length();
    for (int i = 0; i < length; i++) {
        result.append(numStr.charAt(i));
        if ((length - i - 1) % 3 == 0 && i != length - 1) {
            result.append('.');
        }
    }
    return result.toString();
}

public static String addThousandSeparator(int n) {
    if (n == 0) {
        return "0";
    }

    StringBuilder result = new StringBuilder();
    boolean firstDigit = true;

    while (n > 0) {
        result.insert(0, n % 10);
        n /= 10;

        if (n > 0 && (result.length() - 1) % 3 == 0 && !firstDigit) {
            result.insert(0, '.');
        } else {
            firstDigit = false;
        }
    }

    return result.toString();
}

public static String addThousandSeparator(int n) {
    if (n == 0) {
        return "0";
    }

    StringBuilder result = new StringBuilder();
    boolean negative = n < 0;
    if (negative) {
        n = -n;
    }

    int count = 0;
    while (n > 0) {
        if (count > 0 && count % 3 == 0) {
            result.insert(0, '.');
        }
        result.insert(0, n % 10);
        n /= 10;
        count++;
    }

    if (negative) {
        result.insert(0, '-');
    }

    return result.toString();
}

public static String addThousandSeparator(int n) {
    if (n == 0) {
        return "0";
    }
    StringBuilder result = new StringBuilder();
    String numStr = Integer.toString(n);
    int length = numStr.length();
    for (int i = 0; i < length; i++) {
        if (i > 0 && (length - i) % 3 == 0) {
            result.append('.');
        }
        result.append(numStr.charAt(i));
    }
