public static int squarePermutations(int[] A) {
    if (A == null || A.length == 0) {
        return 0;
    }

    int n = A.length;
    int count = 0;

    // Helper function to check if a number is a perfect square
    boolean isPerfectSquare(int num) {
        int root = (int) Math.sqrt(num);
        return root * root == num;
    }

    // Helper function to perform backtracking
    void backtrack(int[] A, int index, int count) {
        if (index == n - 1) {
            this.count++;
            return;
        }

        for (int i = index + 1; i < n; i++) {
            if (isPerfectSquare(A[index] + A[i])) {
                int temp = A[index + 1];
                A[index + 1] = A[i];
                A[i] = temp;

                backtrack(A, index + 1, count);

                temp = A[index + 1];
                A[index + 1] = A[i];
                A[i] = temp;
            }
        }
    }

    // Iterate over each starting position
    for (int i = 0; i < n; i++) {
        for (int j = i + 1; j < n; j++) {
            if (isPerfectSquare(A[i] + A[j])) {
                int temp = A[i + 1];
                A[i + 1] = A[j];
                A[j] = temp;

                backtrack(A, i + 1, count);

                temp = A[i + 1];
                A[i + 1] = A[j];
                A[j] = temp;
            }
        }
    }

    return count;
}

public static int largestRectangleArea(int[] heights) {
    if (heights == null || heights.length == 0) {
        return 0;
    }

    int maxArea = 0;
    Stack<Integer> stack = new Stack<>();

    for (int i = 0; i <= heights.length; i++) {
        int currentHeight = (i == heights.length) ? -1 : heights[i];

        while (!stack.isEmpty() && currentHeight < heights[stack.peek()]) {
            int height = heights[stack.pop()];
            int width = stack.isEmpty() ? i : i - stack.peek() - 1;
            maxArea = Math.max(maxArea, height * width);
        }

        stack.push(i);
    }

    return maxArea;
}

public static int largestRectangleArea(int[] heights) {
