public static int[] diagonalOrder(int[][] mat) {
        if (mat == null || mat.length == 0) {
            return new int[0];
        }

        int rows = mat.length;
        int cols = mat[0].length;
        int[] result = new int[rows * cols];
        int index = 0;

        for (int elevation = 0; elevation < rows + cols - 1; elevation++) {
            if (elevation % 2 == 0) {
                // Traverse up
                for (int row = Math.min(elevation, rows - 1); row >= 0 && elevation - row < cols; row--) {
                    result[index++] = mat[row][elevation - row];
                }
            } else {
                // Traverse down
                for (int col = Math.min(elevation, cols - 1); col >= 0 && elevation - col < rows; col--) {
                    result[index++] = mat[elevation - col][col];
                }
            }
        }

        return result;
    }

