public static int minPerfectSquareSum(int n) {
    if (n <= 0) {
        return 0;
    }

    int[] dp = new int[n + 1];
    for (int i = 1; i <= n; i++) {
        dp[i] = i; // Initialize with the maximum possible (i.e., i = 1 + 1 + ... + 1)
        for (int j = 1; j * j <= i; j++) {
            dp[i] = Math.min(dp[i], dp[i - j * j] + 1);
        }
    }

    return dp[n];
}

public static int minPerfectSquareSum(int n) {
    if (n <= 0) {
        throw new IllegalArgumentException("Input must be a positive integer.");
    }

    int[] dp = new int[n + 1];
    for (int i = 1; i <= n; i++) {
        dp[i] = i; // Worst case: using 1^2 + 1^2 + ... + 1^2
    }

    for (int i = 1; i * i <= n; i++) {
        int square = i * i;
        for (int j = square; j <= n; j++) {
            dp[j] = Math.min(dp[j], dp[j - square] + 1);
        }
    }

    return dp[n];
}

public static int minPerfectSquareSum(int n) {
    // Edge case: If n is less than or equal to 3, the minimum number of perfect squares is n
    if (n <= 3) {
        return n;
    }

    // Initialize an array to store the minimum number of perfect squares for each number up to n
    int[] dp = new int[n + 1];
    for (int i = 0; i <= n; i++) {
        dp[i] = i; // The minimum number of perfect squares for any number i is i (using 1^2 + 1^2 + ...)
    }

    // Iterate over each number from 4 to n to find the minimum number of perfect squares
    for (int i = 4; i <= n; i++) {
        // Iterate over each perfect square smaller than or equal to i
        for (int j = 1; j * j <= i; j++) {
            // Update the dp array with the minimum number of perfect squares for the current number i
            dp[i] = Math.min(dp[i], dp[i - j * j] + 1);
        }
    }

    // Return the minimum number of perfect squares for the target number n
    return dp[n];
}

public static int minPerfectSquareSum(int n) {
    if (n < 0) {
        throw new IllegalArgumentException("n must be a non-negative integer");
    }

    // Array to store the minimum number of squares that sum up to each number
    int[] dp = new int[n + 1];
    for (int i = 1; i <= n; i++) {
        dp[i] = i; // Maximum number of squares is i (1^2 + 1^2 + ...)
    }

    // Compute the minimum number of squares for each number up to n
    for (int i = 2; i <= n; i++) {
        for (int j = 1; j * j <= i; j++) {
            dp[i] = Math.min(dp[i], dp[i - j * j] + 1);
        }
    }

    return dp[n];
}

